object MobileSeedCatalog {

    private fun makeVariants(price: Double, ram: Int, storage: Int): List<DeviceVariant> {
        val v1 = DeviceVariant(
            variantKey = "${storage}gb",
            storageGb = storage,
            ramGb = ram,
            priceTry = price,
            stores = listOf(
                StoreOffer("Hepsiburada", price, "https://www.google.com"),
                StoreOffer("Amazon TR", price + 450.0, "https://www.google.com"),
                StoreOffer("Trendyol", price - 350.0, "https://www.google.com")
            ),
            priceHistory = listOf(
                PricePoint(date = "2024-07", priceTry = (price * 1.05 * 100).toLong() / 100.0),
                PricePoint(date = "2024-08", priceTry = (price * 1.02 * 100).toLong() / 100.0),
                PricePoint(date = "2024-09", priceTry = (price * 1.01 * 100).toLong() / 100.0),
                PricePoint(date = "2024-10", priceTry = price)
            )
        )
        val s2 = if (storage <= 512) storage * 2 else 1024
        if (s2 <= storage) return listOf(v1)
        val p2 = ((price * 1.14) * 100).toLong() / 100.0
        val r2 = if (ram < 16 && storage >= 256) ram + 4 else ram
        val v2 = DeviceVariant(
            variantKey = "${s2}gb",
            storageGb = s2,
            ramGb = r2,
            priceTry = p2,
            stores = listOf(
                StoreOffer("Hepsiburada", p2, "https://www.google.com"),
                StoreOffer("Amazon TR", p2 + 500.0, "https://www.google.com"),
                StoreOffer("Trendyol", p2 - 400.0, "https://www.google.com")
            ),
            priceHistory = listOf(
                PricePoint(date = "2024-07", priceTry = (p2 * 1.05 * 100).toLong() / 100.0),
                PricePoint(date = "2024-08", priceTry = (p2 * 1.02 * 100).toLong() / 100.0),
                PricePoint(date = "2024-09", priceTry = (p2 * 1.01 * 100).toLong() / 100.0),
                PricePoint(date = "2024-10", priceTry = p2)
            )
        )
        if (storage > 256) return listOf(v1, v2)
        val s3 = 1024
        val p3 = ((price * 1.30) * 100).toLong() / 100.0
        val r3 = if (ram < 16) ram + 4 else ram
        val v3 = DeviceVariant(
            variantKey = "${s3}gb",
            storageGb = s3,
            ramGb = r3,
            priceTry = p3,
            stores = listOf(
                StoreOffer("Hepsiburada", p3, "https://www.google.com"),
                StoreOffer("Amazon TR", p3 + 600.0, "https://www.google.com"),
                StoreOffer("Trendyol", p3 - 500.0, "https://www.google.com")
            ),
            priceHistory = listOf(
                PricePoint(date = "2024-07", priceTry = (p3 * 1.05 * 100).toLong() / 100.0),
                PricePoint(date = "2024-08", priceTry = (p3 * 1.02 * 100).toLong() / 100.0),
                PricePoint(date = "2024-09", priceTry = (p3 * 1.01 * 100).toLong() / 100.0),
                PricePoint(date = "2024-10", priceTry = p3)
            )
        )
        return listOf(v1, v2, v3)
    }

    private fun makeTabletVariants(price: Double, ram: Int, storage: Int): List<DeviceVariant> {
        val v1 = DeviceVariant(
            variantKey = "${storage}gb",
            storageGb = storage,
            ramGb = ram,
