    fun getAll(): List<HardwareItem> = getSmartphones() + getTablets()

    fun findById(id: String): HardwareItem? = getAll().find { it.id.value == id }

    private val jsonSerializer = kotlinx.serialization.json.Json {
        ignoreUnknownKeys = true
        isLenient = true
        coerceInputValues = true
    }

    fun parseSmartphonesJson(jsonText: String): List<HardwareItem> = runCatching {
        val dtos = jsonSerializer.decodeFromString<List<com.panda.myapplication.data.model.dto.SmartphoneCatalogItemDto>>(jsonText)
        dtos.mapNotNull { it.toDomain() }
    }.getOrDefault(emptyList())

    fun parseTabletsJson(jsonText: String): List<HardwareItem> = runCatching {
        val dtos = jsonSerializer.decodeFromString<List<com.panda.myapplication.data.model.dto.TabletCatalogItemDto>>(jsonText)
        dtos.mapNotNull { it.toDomain() }
    }.getOrDefault(emptyList())
}
